protocol v1 {                       # .proto / OpenAPI document / SDL: the published contract
  submitOrder(OrderRequest) -> OrderAck
}
# host: translate at the seam; internals never appear on the wire
def submit_order(req: OrderRequest) -> OrderAck:
    order = Orders.create(OrderId(req.id), Money(req.total))   # domain types stay private
    return OrderAck(order.id, Status.ACCEPTED)
